;\r\n            $output .= \'<h2><a href=\"\'. get_permalink() .\'\">\' . get_the_title() . \'</a></h2>\';\r\n            $output .= \'<p>\' . get_the_excerpt() . \'</p>\';\r\n            $output .= \'</div>\';\r\n        }\r\n        $output .= \'</div>\';\r\n        wp_reset_postdata();\r\n        return $output;\r\n    } else {\r\n        return \'<p>Aucun r├®sultat trouv├® pour \"<strong>\' . esc_html($search_query) . \'</strong>\".</p>\';\r\n    }\r\n}\r\nadd_shortcode(\'search_results\', \'custom_search_results_shortcode\');\r\n\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:10:\"everywhere\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}s:13:\"compiled_code\";s:0:\"\";s:8:\"modified\";s:19:\"2025-10-19 11:30:50\";}i:1;a:14:{s:2:\"id\";i:584;s:5:\"title\";s:12:\"cdnss select\";s:4:\"code\";s:1100:\"function cdnss_select_shortcode($atts) {\r\n    $atts = shortcode_atts(array(\r\n        \'options\' => \'Option 1, Option 2, Option 3\', // Default fallback\r\n        \'width\'   => \'100%\',\r\n    ), $atts, \'cdnss_select\');\r\n\r\n    $options = explode(\',\', $atts[\'options\']);\r\n\r\n    ob_start(); ?>\r\n\r\n    <style>\r\n    .cdnss-select {\r\n      position: relative;\r\n      width: <?php echo esc_attr($atts[\'width\']); ?>;\r\n    }\r\n\r\n    .cdnss-select select {\r\n      width: 100%;\r\n      padding: 10px 15px;\r\n      font-size: 14px;\r\n      border: 1px solid #ccc;\r\n      border-radius: 10px;\r\n      background-color: #fff;\r\n      appearance: none;\r\n      -webkit-appearance: none;\r\n      -moz-appearance: none;\r\n      cursor: pointer;\r\n      transition: all 0.3s ease;\r\n    }\r\n\r\n   \r\n\r\n    \r\n    </style>\r\n\r\n    <div class=\"cdnss-select\">\r\n      <select>\r\n        <?php foreach ($options as $option): ?>\r\n          <option><?php echo trim($option); ?></option>\r\n     